define({"topics":[{"title":"Doing a check scan","shortdesc":"<p class=\"shortdesc\"> A check scan is done at the beginning of some procedures and at the end of many procedures. This functional check assures the unit is in good clinical working order.<\/p>","href":"t_DoingACheckScan_Parent_11.html","attributes":{"data-id":"id_2001754"},"menu":{"hasChildren":false},"tocID":"id_2001754-d46e90314","topics":[]},{"title":"Electrical Safety","shortdesc":"<p class=\"shortdesc\">You must follow all recommended safety procedures when servicing and working near energy sources.<\/p>","href":"r_ElectricalSafety_6.html","attributes":{"data-id":"id_2001693"},"menu":{"hasChildren":false},"tocID":"id_2001693-d46e90418","topics":[]},{"title":"<span class=\"ph\">Shutting down the host computer<\/span>","shortdesc":"<p class=\"shortdesc\">Shutting down the host computer shuts down the system safely and turns off the power to the host computer.<\/p>","href":"t_ShuttingDownHostComputer_Parent_8.html","attributes":{"data-id":"id_2001469"},"menu":{"hasChildren":false},"tocID":"id_2001469-d46e90522","topics":[]},{"title":"Applying LOTO - Integrated System Cabinet (ISC)","shortdesc":"<p class=\"shortdesc\">Apply LOTO to the Power Distribution Unit (PDU) when servicing this item in the Integrated System Cabinet (ISC). Applying LOTO ensures a safe environment when working on this part.<\/p>","href":"t_LOTO-for-ISC-Integrated-System-Cabinet_14845718_7.html","attributes":{"data-id":"id_13106290"},"menu":{"hasChildren":false},"tocID":"id_13106290-d46e90627","topics":[]},{"title":"Removing the Physiological Acquisition Wireless Station (PAWS)","shortdesc":"<p class=\"shortdesc\">Remove the Physiological Acquisition Wireless (PAWS) from the magnet outer electronics.<\/p>","href":"t_RemovingPhysiologicalAcquisitionWirelessStation_PAWS.html","attributes":{"data-id":"id_2037126"},"menu":{"hasChildren":false},"tocID":"id_2037126-d46e90731","topics":[]},{"title":"Installing the Physiological Acquisition Wireless Station (PAWS)","shortdesc":"<p class=\"shortdesc\">Install a Physiological Acquisition Wireless Station (PAWS) in the magnet outer electronics.<\/p>","href":"t_InstallingThePhysiologicalAcquisitionWirelessStationPAWS_PioneerVoyagerHeroPremier.html","attributes":{"data-id":"id_2037129"},"menu":{"hasChildren":false},"tocID":"id_2037129-d46e90835","topics":[]},{"title":"Removing LOTO - Integrated System Cabinet (ISC)","shortdesc":"<p class=\"shortdesc\">Removing locks and tags, and restoring power to the ISC (Integrated System Cabinet) Power Distribution Unit (PDU).<\/p>","href":"t_Removing-LOTO-ISC-Pioneer_6.html","attributes":{"data-id":"id_2016646"},"menu":{"hasChildren":false},"tocID":"id_2016646-d46e90939","topics":[]},{"title":"Starting up the host computer","shortdesc":"<p class=\"shortdesc\">How to start the host computer.<\/p>","href":"t_StartingUpTheHostComputer_10.html","attributes":{"data-id":"id_2001468"},"menu":{"hasChildren":false},"tocID":"id_2001468-d46e91043","topics":[]},{"title":"Finalizing the Physiological Acquisition Wireless Station (PAWS) replacement","shortdesc":"<p class=\"shortdesc\">This procedure finalizes the Physiological Acquisition Wireless Station (PAWS) replacement.<\/p>","href":"t_FinalizingThePhysiologicalAcquisitionWirelessStationPAWSReplacement.html","attributes":{"data-id":"id_2037132"},"menu":{"hasChildren":false},"tocID":"id_2037132-d46e91147","topics":[]}]});